-- =====================================================================
-- Radar - carga inicial
-- 953 oportunidades: 475 cerradas ganadas de 2026 y 478 de cartera abierta.
-- Reglas aplicadas:
--   - Se respeta la probabilidad heredada de Holded, Stand By incluidas.
--   - Se carga la fecha real de ultima actividad.
--   - Las 21 sin comercial entran sin dueno, visibles solo para direccion.
--   - Stand By entra sin cierre previsto y con revision el 15/10/2026.
-- Hay 21 titulos repetidos que son operaciones distintas, asi que el enlace
-- con los presupuestos se hace por una referencia de carga, no por el titulo.
-- Ejecutar DESPUES de radar_v3.sql, de una vez y entero.
-- =====================================================================


alter table radar.oportunidad add column if not exists ref_carga text;

-- --- Direccion -------------------------------------------------------
-- Enlaza por correo con los usuarios invitados en Authentication.
-- Si alguno aun no existe, esa fila no se crea y se relanza mas tarde.
insert into radar.perfil (id, nombre, email, rol, tag_comercial)
select u.id, v.nombre, v.email, 'director', v.tag
from (values
  ('Alejandro Puig', 'apuig@onsecur.es',    'alejandropuig'),
  ('Max Flaquer',    'mflaquer@onsecur.es', null)
) as v(nombre, email, tag)
join auth.users u on u.email = v.email
on conflict (id) do update
  set rol = excluded.rol, tag_comercial = excluded.tag_comercial;

