update radar.oportunidad o set cuenta_id = c.id
  from radar.cuenta c where lower(c.nombre) = lower(o.cliente) and o.cuenta_id is null;

update radar.oportunidad o set comercial = c.propietario
  from radar.cuenta c
 where c.id = o.cuenta_id and c.propietario is not null
   and o.comercial is distinct from c.propietario;

