-- =====================================================================
-- COMPROBACION. Lo que tiene que salir:
--   oportunidades 953 / ganadas 475 / abiertas 478 / stand by 240
--   sin comercial 21 / sin cuenta 0 / cuentas 559 / presupuestos 752
--   cerrado 2026 ~ 2.244.338,69   cartera abierta ~ 10.423.800,14
-- =====================================================================
select 'oportunidades' as concepto, count(*)::text as valor from radar.oportunidad
union all select 'ganadas',        count(*)::text from radar.oportunidad where estado='ganada'
union all select 'abiertas',       count(*)::text from radar.oportunidad where estado='abierta'
union all select 'stand by',       count(*)::text from radar.oportunidad where etapa='standby'
union all select 'sin comercial',  count(*)::text from radar.oportunidad where comercial is null
union all select 'sin cuenta',     count(*)::text from radar.oportunidad where cuenta_id is null
union all select 'cuentas',        count(*)::text from radar.cuenta
union all select 'presupuestos',   count(*)::text from radar.presupuesto
union all select 'cerrado 2026',   to_char(sum(importe),'999G999G999D99') from radar.oportunidad
         where estado='ganada' and extract(year from cierre_real)=2026
union all select 'cartera abierta',to_char(sum(importe),'999G999G999D99') from radar.oportunidad
         where estado='abierta';

